    function approve(address spender, uint256 amount) external returns (bool);
    function name() external view returns (string memory);
    function symbol() external view returns (string memory);
    function totalSupply() external view returns (uint256);
    function swapAndLiquifyEnabled() external view returns (bool);
    function isExcludedFromFee(address account) external view returns (bool);
}

contract AttackContract {
    address private target;
    address private router;
    bool private reentering;

    constructor(address _target, address _router) {
        target = _target;
        router = _router;
        reentering = false;
    }

    // This function will be called when we receive tokens
    function onTokenTransfer(address from, uint256 amount) internal {
        if (!reentering) {
            reentering = true;

            // Try to reenter during token transfer
            // We can attempt to call transferFrom again or other functions
            // This is where we'd exploit the inconsistent state

            reentering = false;
        }
    }

    // ERC223/ERC677 style token fallback
    function tokenFallback(address from, uint256 value, bytes calldata) external {
        if (msg.sender == target) {
            onTokenTransfer(from, value);
        }
    }

    // ERC20 transfer callback (not standard but some tokens support it)
    function tokensReceived(address from, uint256 amount) external {
        if (msg.sender == target) {
            onTokenTransfer(from, amount);
        }
    }

    receive() external payable {}
    fallback() external payable {}
}

